import { useState, type FormEvent } from 'react';
import { Plus, Edit2, Trash2, HelpCircle, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import I18nInput from '@/components/I18nInput';
import { useFaqs, type IFaq } from '@/hooks/useFaqs';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';

interface FaqForm {
  question: I18nText;
  answer: I18nText;
  order: number;
}

export default function AdminFaqsPage() {
  const { adminT, adminLanguage } = useI18n();
  const { faqs, addFaq, updateFaq, deleteFaq } = useFaqs();
  const { markDirty, syncModule, syncJsonFile, getStatus } = useSyncService();
  const syncStatus = getStatus('faqs');

  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FaqForm>({
    question: createI18nText(''),
    answer: createI18nText(''),
    order: 1,
  });

  const handleAdd = () => {
    setEditingId(null);
    const nextOrder = faqs.length > 0 ? Math.max(...faqs.map((f) => f.order)) + 1 : 1;
    setForm({
      question: createI18nText(''),
      answer: createI18nText(''),
      order: nextOrder,
    });
    setDialogOpen(true);
  };

  const handleEdit = (faq: IFaq) => {
    setEditingId(faq.id);
    setForm({
      question: faq.question,
      answer: faq.answer,
      order: faq.order,
    });
    setDialogOpen(true);
  };

  const handleDelete = (id: string) => {
    if (!window.confirm(adminT('admin.confirmDelete'))) return;
    deleteFaq(id);
    toast.success('FAQ deleted');
    markDirty('faqs');
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.question.en.trim()) {
      toast.error('Question (English) is required');
      return;
    }
    if (!form.answer.en.trim()) {
      toast.error('Answer (English) is required');
      return;
    }

    if (editingId) {
      updateFaq(editingId, form);
      toast.success('FAQ updated');
    } else {
      addFaq(form);
      toast.success('FAQ added');
    }
    setDialogOpen(false);
    markDirty('faqs');
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.faqs'), href: '/admin/faqs' }]}
      />

      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-bold text-foreground">{adminT('admin.faqs')}</h1>
              <SyncStatusBadge status={syncStatus} />
            <Button
              variant="outline"
              size="sm"
              onClick={() =>
                syncModule('faqs', 'FAQs', async (config) => {
                  await syncJsonFile(
                    config,
                    'data/faqs.json',
                    faqs,
                    'Update FAQ data'
                  );
                })
              }
              disabled={syncStatus === 'syncing'}
              className="text-xs h-9"
            >
              <Upload className="size-3.5 mr-1.5" />
              Sync to GitHub
            </Button>
          </div>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.faqsDesc')}
          </p>
        </div>
        <Button onClick={handleAdd} className="gap-2">
          <Plus className="size-4" />
          {adminT('admin.addFaq')}
        </Button>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-lg">
            <HelpCircle className="size-5 text-primary" />
            {adminT('admin.faqList')}
            <span className="ml-2 text-sm font-normal text-muted-foreground">
              ({faqs.length} {adminT('admin.items')})
            </span>
          </CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-16 whitespace-nowrap">Order</TableHead>
                  <TableHead className="whitespace-nowrap">Question</TableHead>
                  <TableHead className="w-24 whitespace-nowrap text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {faqs.map((faq) => (
                  <TableRow key={faq.id}>
                    <TableCell className="font-mono text-sm">{faq.order}</TableCell>
                    <TableCell className="font-medium">
                      <div className="font-semibold text-foreground">
                        {faq.question[adminLanguage] || faq.question.en}
                      </div>
                      <div className="text-sm text-muted-foreground line-clamp-2 mt-1">
                        {faq.answer[adminLanguage] || faq.answer.en}
                      </div>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleEdit(faq)}
                          aria-label="Edit"
                        >
                          <Edit2 className="size-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => handleDelete(faq.id)}
                          aria-label="Delete"
                          className="text-destructive hover:text-destructive"
                        >
                          <Trash2 className="size-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
                {faqs.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={3} className="text-center text-muted-foreground py-12">
                      No FAQs yet. Click "Add FAQ" to create one.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Add/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-2xl max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingId ? adminT('admin.editFaq') : adminT('admin.addFaq')}
            </DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="text-sm font-medium text-foreground mb-2 block">
                {adminT('admin.faqQuestion')} <span className="text-destructive">*</span>
              </label>
              <I18nInput
                value={form.question}
                onChange={(val) => setForm({ ...form, question: val })}
                placeholder="Enter question..."
              />
            </div>
            <div>
              <label className="text-sm font-medium text-foreground mb-2 block">
                {adminT('admin.faqAnswer')} <span className="text-destructive">*</span>
              </label>
              <I18nInput
                value={form.answer}
                onChange={(val) => setForm({ ...form, answer: val })}
                placeholder="Enter answer..."
                multiline
                rows={4}
              />
            </div>
            <div>
              <label className="text-sm font-medium text-foreground mb-2 block">
                {adminT('admin.sortOrder')}
              </label>
              <Input
                type="number"
                value={form.order}
                onChange={(e) => setForm({ ...form, order: parseInt(e.target.value) || 0 })}
                min={1}
              />
            </div>
            <DialogFooter>
              <Button type="button" variant="secondary" onClick={() => setDialogOpen(false)}>
                {adminT('admin.cancel')}
              </Button>
              <Button type="submit">
                {editingId ? adminT('admin.save') : adminT('admin.add')}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
